python3 << 'EOF' > transcript.txt
import json

def extract_text(content):
    if isinstance(content, str):
        return content
    out = []
    if isinstance(content, list):
        for c in content:
            if isinstance(c, dict):
                if c.get("type") == "text":
                    out.append(c.get("text",""))
                elif c.get("type") == "tool_use":
                    out.append(f"[TOOL_USE {c.get('name')}] input={json.dumps(c.get('input'))[:500]}")
                elif c.get("type") == "tool_result":
                    cont = c.get("content")
                    if isinstance(cont, list):
                        cont = " ".join(x.get("text","") for x in cont if isinstance(x, dict))
                    out.append(f"[TOOL_RESULT] {str(cont)[:500]}")
    return "\n".join(out)

for fname in ["a.jsonl","b.jsonl"]:
    print("=====", fname, "=====")
    with open(fname) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            typ = obj.get("type")
            ts = obj.get("timestamp")
            if typ in ("user","assistant"):
                msg = obj.get("message", {})
                role = msg.get("role")
                content = msg.get("content")
                text = extract_text(content)
                if text.strip():
                    print(f"--- [{i}] {ts} {role} ---")
                    print(text[:2000])
EOF
