python3 << 'EOF'
import json
lines = open('log.jsonl').readlines()
out = []
for i,l in enumerate(lines):
    d = json.loads(l)
    ts = d.get('timestamp')
    typ = d.get('type')
    if typ == 'assistant':
        msg = d.get('message',{})
        content = msg.get('content',[])
        for c in content:
            if c.get('type')=='text':
                txt = c['text'][:300].replace('\n',' | ')
                out.append((i, ts, 'A-text', txt))
            elif c.get('type')=='tool_use':
                name = c.get('name')
                inp = json.dumps(c.get('input',{}))[:300]
                out.append((i, ts, f'A-tool:{name}', inp))
    elif typ == 'user':
        msg = d.get('message',{})
        content = msg.get('content',[])
        if isinstance(content,str):
            out.append((i, ts, 'U-text', content[:300]))
        else:
            for c in content:
                if isinstance(c,dict) and c.get('type')=='tool_result':
                    cont = c.get('content')
                    if isinstance(cont,list):
                        s=''
                        for cc in cont:
                            if isinstance(cc,dict) and cc.get('type')=='text':
                                s+=cc['text']
                    else:
                        s = str(cont)
                    out.append((i, ts, 'U-toolresult', s[:300].replace('\n',' | ')))
                elif isinstance(c,dict) and c.get('type')=='text':
                    out.append((i, ts, 'U-text', c['text'][:300]))
with open('timeline.txt','w') as f:
    for row in out:
        f.write(f"{row[0]}\t{row[1]}\t{row[2]}\t{row[3]}\n")
print(len(out))
EOF
wc -l timeline.txt

